#!/usr/bin/env bash
# Sign the unsigned HAP with the SDK's hap-sign-tool.jar (localSign mode).
#
# Material comes from signing/signing.env (git-ignored) or the environment:
#   SIGN_KEYSTORE   *.p12 keystore generated by DevEco / AGC / generate-keypair
#   SIGN_KEY_ALIAS  key alias inside the keystore        (DevEco default: debugKey)
#   SIGN_KEY_PWD    key password
#   SIGN_STORE_PWD  keystore password
#   SIGN_CERT       *.cer application signing certificate
#   SIGN_PROFILE    *.p7b signed provisioning profile (must match the bundleName)
#   SIGN_ALG        SHA256withECDSA (default) | SHA256withRSA
#
# Usage: scripts/sign.sh [--install]
set -euo pipefail

ROOT=$(cd "$(dirname "$0")/.." && pwd)
CLT=${CLT:-$HOME/opt/apps/harmonyos/26.0.0.865/command-line-tools}
LIB="$CLT/sdk/default/openharmony/toolchains/lib"
HDC="$CLT/sdk/default/openharmony/toolchains/hdc"

[[ -f "$ROOT/signing/signing.env" ]] && source "$ROOT/signing/signing.env"

: "${SIGN_KEYSTORE:?set SIGN_KEYSTORE}"
: "${SIGN_KEY_ALIAS:?set SIGN_KEY_ALIAS}"
: "${SIGN_KEY_PWD:?set SIGN_KEY_PWD}"
: "${SIGN_STORE_PWD:?set SIGN_STORE_PWD}"
: "${SIGN_CERT:?set SIGN_CERT}"
: "${SIGN_PROFILE:?set SIGN_PROFILE}"
SIGN_ALG=${SIGN_ALG:-SHA256withECDSA}

IN="$ROOT/entry/build/default/outputs/default/entry-default-unsigned.hap"
OUT="$ROOT/entry/build/default/outputs/default/entry-default-signed.hap"
[[ -f "$IN" ]] || { echo "missing $IN — run assembleHap first" >&2; exit 1; }

for f in "$SIGN_KEYSTORE" "$SIGN_CERT" "$SIGN_PROFILE"; do
  [[ -f "$f" ]] || { echo "missing signing material: $f" >&2; exit 1; }
done

java -jar "$LIB/hap-sign-tool.jar" sign-app \
  -mode localSign \
  -keyAlias "$SIGN_KEY_ALIAS" \
  -keyPwd "$SIGN_KEY_PWD" \
  -appCertFile "$SIGN_CERT" \
  -profileFile "$SIGN_PROFILE" \
  -inFile "$IN" \
  -signAlg "$SIGN_ALG" \
  -keystoreFile "$SIGN_KEYSTORE" \
  -keystorePwd "$SIGN_STORE_PWD" \
  -outFile "$OUT" \
  -compatibleVersion 26 \
  -signCode 1

echo "signed: $OUT"

if [[ "${1:-}" == "--install" ]]; then
  "$HDC" install -r "$OUT"
fi
